// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "5"
//   input[1] は "2 1 4 3 5"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [first, second] = readFileSync(0, "utf8").trim().split("\n");
const n = Number(first);
const a = second.split(" ").map(Number);

const answer = new Array(n).fill(-1);
// まだ答えが決まっていない添字を、値が減少する順に積んでおく
const stack: number[] = [];
for (let i = 0; i < n; i++) {
  while (stack.length > 0 && a[stack[stack.length - 1]] < a[i]) {
    answer[stack.pop()!] = a[i];
  }
  stack.push(i);
}
console.log(answer.join(" "));
